\set ON_ERROR_STOP on
begin;
create function pg_temp.check_true(condition boolean,message text) returns void language plpgsql as $$begin if condition is distinct from true then raise exception 'Failed: %',message;end if;end$$;
insert into auth.users(id) values('f0000000-0000-4000-8000-000000000001');
insert into public.codex_accounts(id,owner_id,name,identity_key) values('f0000000-0000-4000-8000-000000000002','f0000000-0000-4000-8000-000000000001','Test account','codex-v2:test');
insert into public.codex_devices(id,owner_id,account_id,name,token_hash,confirmed_identity) values('f0000000-0000-4000-8000-000000000003','f0000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000002','Mac A',repeat('a',64),'codex-v2:test'),('f0000000-0000-4000-8000-000000000004','f0000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000002','Mac B',repeat('b',64),'codex-v2:test');
create function pg_temp.ingest(device text,hash text,batch text,stamp timestamptz,tokens bigint,identity text default 'codex-v2:test') returns jsonb language sql as $$select public.codex_ingest(device::uuid,repeat(hash,64),jsonb_build_object('type','observation','batchId',batch,'collectedAt',stamp,'identityKey',identity,'identityLabel','test@example.test','usageStatus','ok','quotaStatus','ok','daily',jsonb_build_array(jsonb_build_object('date',current_date,'tokens',tokens)),'quotaWindows','[]'::jsonb,'summary','null'::jsonb))$$;
select pg_temp.check_true((pg_temp.ingest('f0000000-0000-4000-8000-000000000003','a','f1000000-0000-4000-8000-000000000001',now(),100)->>'ok')::boolean,'initial batch');
update public.codex_devices set heartbeat_at=null;
select pg_temp.check_true((pg_temp.ingest('f0000000-0000-4000-8000-000000000003','a','f1000000-0000-4000-8000-000000000001',now(),999)->>'duplicate')::boolean,'duplicate idempotent');
select pg_temp.check_true((select tokens=100 from public.codex_daily_usage where account_id='f0000000-0000-4000-8000-000000000002'),'duplicate cannot replace daily');
select pg_temp.ingest('f0000000-0000-4000-8000-000000000004','b','f1000000-0000-4000-8000-000000000002',now()-interval '1 minute',80);
select pg_temp.check_true((select tokens=100 from public.codex_daily_usage where account_id='f0000000-0000-4000-8000-000000000002'),'out of order across Macs');
update public.codex_devices set heartbeat_at=null;
select pg_temp.ingest('f0000000-0000-4000-8000-000000000004','b','f1000000-0000-4000-8000-000000000003',now()+interval '1 second',120);
select pg_temp.check_true((select count(*)=1 and sum(tokens)=120 from public.codex_daily_usage where account_id='f0000000-0000-4000-8000-000000000002'),'multiple Macs replace absolute daily values');
update public.codex_accounts set quota_windows='[{"bucket":"codex","kind":"primary","usedPercent":25,"windowDurationMins":300,"resetsAt":null}]',summary='{"lifetimeTokens":0}' where id='f0000000-0000-4000-8000-000000000002';
update public.codex_devices set heartbeat_at=null;
select public.codex_ingest('f0000000-0000-4000-8000-000000000004',repeat('b',64),jsonb_build_object('type','observation','batchId','f2000000-0000-4000-8000-000000000001','collectedAt',now()+interval '2 seconds','identityKey','codex-v2:test','usageStatus','error','quotaStatus','error','daily','[]'::jsonb,'quotaWindows','[]'::jsonb,'summary','null'::jsonb));
select pg_temp.check_true((select tokens=120 from public.codex_daily_usage where account_id='f0000000-0000-4000-8000-000000000002'),'failed usage preserves daily');
select pg_temp.check_true((select jsonb_array_length(quota_windows)=1 and summary->>'lifetimeTokens'='0' and quota_status='error' from public.codex_accounts where id='f0000000-0000-4000-8000-000000000002'),'failed capabilities preserve previous quota and measured zero summary');
select pg_temp.check_true((select last_error='collection_error' from public.codex_devices where id='f0000000-0000-4000-8000-000000000004'),'device exposes collection failure');
update public.codex_devices set heartbeat_at=null;
select pg_temp.check_true((pg_temp.ingest('f0000000-0000-4000-8000-000000000003','a','f1000000-0000-4000-8000-000000000004',now(),900,'codex-v2:new')->>'confirmationRequired')::boolean,'identity switch gated');
select pg_temp.check_true((select tokens=120 from public.codex_daily_usage where account_id='f0000000-0000-4000-8000-000000000002'),'identity switch preserves history');
do $$begin perform public.codex_confirm_identity('f0000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000003','codex-v2:new');raise exception 'identity replacement was allowed';exception when sqlstate 'P0001' then if sqlerrm<>'new_account_required' then raise;end if;end$$;
select public.codex_confirm_identity('f0000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000003','codex-v2:new',null,'New identity','work');
select pg_temp.check_true((select count(*)=2 from public.codex_accounts where owner_id='f0000000-0000-4000-8000-000000000001'),'identity change creates separate account');
update public.codex_devices set heartbeat_at=null,paused=true where id='f0000000-0000-4000-8000-000000000004';
select pg_temp.check_true((pg_temp.ingest('f0000000-0000-4000-8000-000000000004','b','f1000000-0000-4000-8000-000000000005',now(),777)->>'paused')::boolean,'paused upload ignored');
update public.codex_devices set revoked_at=now() where id='f0000000-0000-4000-8000-000000000004';
do $$begin perform pg_temp.ingest('f0000000-0000-4000-8000-000000000004','b','f1000000-0000-4000-8000-000000000006',now(),777);raise exception 'revoked upload was allowed';exception when sqlstate 'P0001' then if sqlerrm<>'device_revoked' then raise;end if;end$$;
select pg_temp.check_true(not has_function_privilege('anon','public.codex_ingest(uuid,text,jsonb)','execute'),'anonymous RPC denied');
select pg_temp.check_true(not has_column_privilege('authenticated','public.codex_devices','token_hash','select'),'credential hash hidden');
set local role authenticated;
select pg_temp.check_true((select count(*)=0 from public.codex_accounts),'RLS hides other owner account');
reset role;
insert into public.codex_pairings(code_hash,owner_id,account_id,expires_at) values(repeat('c',64),'f0000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000002',now()+interval '10 minutes');
insert into public.codex_pairings(code_hash,owner_id,account_id,expires_at) values(repeat('f',64),'f0000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000002',now());
do $$begin perform public.codex_pair_device(repeat('f',64),'Expired pair',repeat('d',64),'test');raise exception 'expired pair code accepted';exception when sqlstate 'P0001' then if sqlerrm<>'pairing_expired' then raise;end if;end$$;
select public.codex_pair_device(repeat('c',64),'Pair test',repeat('d',64),'test');
do $$begin perform public.codex_pair_device(repeat('c',64),'Pair duplicate',repeat('d',64),'test');raise exception 'pair code reused';exception when sqlstate 'P0001' then if sqlerrm<>'pairing_expired' then raise;end if;end$$;
update public.codex_accounts set paused=true where id='f0000000-0000-4000-8000-000000000002';
select public.codex_delete_history('f0000000-0000-4000-8000-000000000001','f0000000-0000-4000-8000-000000000002');
select pg_temp.check_true((select count(*)=0 from public.codex_daily_usage where account_id='f0000000-0000-4000-8000-000000000002'),'explicit history deletion');
rollback;
\echo 'PASS: Codex SQL idempotency ordering identity lifecycle RLS pairing history'
